function cookableDishes(recipes: string[], ingredients: string[][], supplies: string[]): string[] {
  const have = new Set(supplies), done = new Array(recipes.length).fill(false), out: string[] = [];
  let changed = true;
  while (changed) {
    changed = false;
    for (let i = 0; i < recipes.length; i++) {
      if (done[i] || !ingredients[i].every(x => have.has(x))) continue;
      done[i] = true;
      have.add(recipes[i]);
      out.push(recipes[i]);
      changed = true;
    }
  }
  return out;
}

