    def cookableDishes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        have, done, out = set(supplies), [False] * len(recipes), []
        changed = True
        while changed:
            changed = False
            for i, dish in enumerate(recipes):
                if not done[i] and all(x in have for x in ingredients[i]):
                    done[i] = True
                    have.add(dish)
                    out.append(dish)
                    changed = True
        return out

