function cookableDishes(recipes: string[], ingredients: string[][], supplies: string[]): string[] {
  const users = new Map<string, number[]>();
  const missing = ingredients.map(list => list.length);
  ingredients.forEach((list, i) => {
    for (const item of list) {
      if (!users.has(item)) users.set(item, []);
      users.get(item)!.push(i);
    }
  });
  const queue = [...supplies], out: string[] = [];
  for (let h = 0; h < queue.length; h++) {
    for (const i of users.get(queue[h]) ?? []) {
      if (--missing[i] === 0) {
        out.push(recipes[i]);
        queue.push(recipes[i]);
      }
    }
  }
  return out;
}

